static int pcm_capture_trigger ( struct snd_pcm_substream * substream , int cmd ) { struct snd_tscm * tscm = substream -> private_data ; switch ( cmd ) { case SNDRV_PCM_TRIGGER_START : amdtp_stream_pcm_trigger ( & tscm -> tx_stream , substream ) ; break ; case SNDRV_PCM_TRIGGER_STOP : amdtp_stream_pcm_trigger ( & tscm -> tx_stream ) ; break ; default : return - EINVAL ; } return 0 ; } 